"use client";

import { useState, useMemo } from "react";
import { motion } from "framer-motion";
import { Search, Globe, Network, Zap } from "lucide-react";
import Link from "next/link";
import Flag from "@/components/ui/Flag";
import Skeleton from "@/components/ui/Skeleton";
import Pagination from "@/components/ui/Pagination";
import { useASNs } from "@/hooks/useData";

export default function ASNPage() {
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 12;

  const { asns, loading, error } = useASNs();

  const groupedByCountry = useMemo(() => {
    if (!asns) return [];

    const countryMap = new Map<
      string,
      { code: string; name: string; asns: number }
    >();

    asns.forEach((asn) => {
      const code = asn.country_code;
      if (!countryMap.has(code)) {
        countryMap.set(code, { code, name: code, asns: 0 });
      }
      countryMap.get(code)!.asns += 1;
    });

    return Array.from(countryMap.values());
  }, [asns]);

  const filteredCountries = useMemo(() => {
    return groupedByCountry.filter((c) =>
      c.code.toLowerCase().includes(searchQuery.toLowerCase()),
    );
  }, [groupedByCountry, searchQuery]);

  const totalPages = Math.ceil(filteredCountries.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const currentCountries = filteredCountries.slice(startIndex, endIndex);

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-12 w-64" />
        <Skeleton className="h-12 w-full" variant="card" />
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {[...Array(10)].map((_, i) => (
            <Skeleton key={i} className="h-20 w-full" variant="card" />
          ))}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-16">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-[rgba(255,95,87,.08)] border border-[rgba(255,95,87,.1)] mb-4">
          <Network size={28} className="text-[#ff5f57]" />
        </div>
        <p className="text-[#ff9b85] font-mono">
          Error loading ASN data: {error}
        </p>
        <button
          onClick={() => window.location.reload()}
          className="mt-4 px-6 py-2.5 bg-[#22e57a] text-[#05100a] font-mono font-bold rounded-lg hover:bg-[#5cffa5] transition-colors"
        >
          Retry
        </button>
      </div>
    );
  }

  if (!asns || asns.length === 0) {
    return (
      <div className="text-center py-16">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-[rgba(34,229,122,.08)] border border-[rgba(34,229,122,.1)] mb-4">
          <Globe size={28} className="text-[#4f6459]" />
        </div>
        <p className="text-[#93a79d] font-mono">No ASN data found</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold font-mono text-[#f2fff8]">
            ASN Database
          </h1>
          <p className="text-[#6f8a7d] text-sm mt-0.5 font-mono">
            {groupedByCountry.length} countries · {asns.length.toLocaleString()}{" "}
            ASNs
          </p>
        </div>
        <div className="relative w-full sm:w-72">
          <Search
            className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#6f8a7d]"
            size={16}
          />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setCurrentPage(1);
            }}
            placeholder="Search by country code..."
            className="w-full bg-[#070b09]/60 border border-[rgba(34,229,122,.1)] rounded-xl pl-10 pr-4 py-2.5 text-sm text-[#c6d2ca] placeholder-[#4f6459] focus:outline-none focus:border-[rgba(34,229,122,.3)] focus:ring-1 focus:ring-[rgba(34,229,122,.15)] transition-all duration-200 font-mono"
          />
        </div>
      </div>

      <p className="text-xs font-mono text-[#4f6459]">
        Showing {currentCountries.length} of {filteredCountries.length}{" "}
        countries
        {searchQuery && ` matching "${searchQuery}"`}
      </p>

      {/* Countries Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {currentCountries.map((country, index) => (
          <motion.div
            key={country.code}
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.03 }}
            whileHover={{ y: -4 }}
          >
            <Link
              href={`/asn/${country.code.toLowerCase()}`}
              className="block bg-[#070b09]/60 border border-[rgba(34,229,122,.06)] hover:border-[rgba(34,229,122,.2)] rounded-xl p-4 transition-all duration-300 group"
            >
              <div className="flex items-center gap-4">
                <Flag countryCode={country.code} size={44} variant="rounded" />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <h3 className="font-mono font-bold text-base group-hover:text-[#22e57a] transition-colors">
                      {country.code}
                    </h3>
                    <span className="text-xs px-1.5 py-0.5 rounded bg-[rgba(34,229,122,.06)] text-[#6f8a7d] font-mono border border-[rgba(34,229,122,.06)]">
                      {country.asns}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 text-xs text-[#4f6459] mt-0.5">
                    <Network size={12} />
                    <span>{country.asns.toLocaleString()} ASNs</span>
                  </div>
                </div>
                <div className="flex-shrink-0">
                  <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md bg-[rgba(34,229,122,.04)] border border-[rgba(34,229,122,.06)] text-[8px] font-mono font-bold text-[#22e57a] tracking-wider">
                    <Zap size={8} />
                    LIVE
                  </span>
                </div>
              </div>
            </Link>
          </motion.div>
        ))}
      </div>

      {filteredCountries.length === 0 && (
        <div className="text-center py-12 bg-[#070b09]/40 border border-[rgba(34,229,122,.06)] rounded-lg">
          <p className="text-[#6f8a7d] font-mono">
            No countries found matching "{searchQuery}"
          </p>
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={handlePageChange}
          className="mt-6"
        />
      )}

      {/* Results count */}
      {filteredCountries.length > 0 && (
        <div className="text-center text-xs font-mono text-[#4f6459]">
          Showing {startIndex + 1} -{" "}
          {Math.min(endIndex, filteredCountries.length)} of{" "}
          {filteredCountries.length} countries
        </div>
      )}
    </div>
  );
}
